peso = 72
altura = 1.75

imc = peso / altura ** 2

if imc < 18.5:
    categoria = "bajo"
elif imc < 25:
    categoria = "normal"
elif imc < 30:
    categoria = "sobrepeso"
else:
    categoria = "obesidad"

print(f"IMC: {imc:.1f} - {categoria}")

